36.99359,-2.06804],[36.99356,-2.06801],[36.99354,-2.06798],[36.99351,-2.06794],[36.99349,-2.06791],[36.99346,-2.06788],[36.99343,-2.06784],[36.9934,-2.0678],[36.99337,-2.06776],[36.99334,-2.06773],[36.99331,-2.06769],[36.99328,-2.06765],[36.99325,-2.06761]]$coords$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  select h.id,h.latitude,h.longitude,h.distance_km,t.status,t.geometry_source_url
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-3725552'
      and h.source='openstreetmap'
      and h.name='Vía Verde de Lucainena de las Torres a Agua Amarga'
      and h.route_type='Lineal'
      and h.official_url='https://caminosnaturales.es/es/red-de-caminos-naturales/camino-detalle/sector-sur/lucainena'
      and h.raw_tags->>'from'='Lucainena de las Torres'
      and h.raw_tags->>'to'='Venta del Pobre'
      and (abs(h.distance_km-15.5)<0.02 or
        (t.status='ready' and abs(h.distance_km-15.59)<0.02))
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='almeria' and r.published);
  if not found then
    raise exception 'Lucainena route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://caminosnaturales.es/dam/caminos-naturales/caminos-naturales/Sector_V_Sur/lucainena/documentacion/0515_lucainena-aguaamargagpx_553776.zip' then
      return;
    end if;
    raise exception 'Lucainena route has another ready trace';
  end if;
  if v_route.status<>'missing' then
    raise exception 'Lucainena status changed: %',v_route.status;
  end if;

  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 27 and 45 and lon between -19 and 5) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;

  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(-2.202129978686571,37.04348998144269)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(-2.067609988152981,36.99325002729893))
    into v_start_gap_m,v_end_gap_m;

  if v_count<>3548 or v_invalid>0
    or abs(v_length_km-15.586)>0.04
    or abs(v_length_km-v_route.distance_km)>0.2
    or v_max_gap_km>0.02 or v_center_gap_km>1.2
    or v_start_gap_m>2 or v_end_gap_m>2 then
    raise exception 'Lucainena GPS validation failed: points %, length %, gap %, center %, start %, end %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_invalid;
  end if;

  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);

  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values (
    v_route.id,'ready',jsonb_build_array(v_points),now(),true,
    'Ministerio de Agricultura - GPX oficial',
    'https://caminosnaturales.es/dam/caminos-naturales/caminos-naturales/Sector_V_Sur/lucainena/documentacion/0515_lucainena-aguaamargagpx_553776.zip',true
  )
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,
    checked_at=excluded.checked_at,continuity_checked=true,
    geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;

  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),
      description='El tramo acondicionado va de Lucainena de las Torres a Venta del Pobre y no llega a Agua Amarga. Cruza pequeñas carreteras y comparte algunos tramos con vehículos; sigue la señalización y el trazado oficial.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'Lucainena publication state changed';
  end if;
end
$curate$;
